export const exportProfiles={balanced:{quality:.85,maxDimension:2400},small:{quality:.65,maxDimension:1600},archive:{quality:.96,maxDimension:0}};
export function readExportPreferences(storage=localStorage){try{const value=JSON.parse(storage.getItem('waraqa-export-preferences')||'{}');return{profile:(Object.hasOwn(exportProfiles,value.profile)||value.profile==='custom')?value.profile:'balanced',size:['a4','letter','original'].includes(value.size)?value.size:'a4',orientation:value.orientation==='landscape'?'landscape':'portrait',searchable:value.searchable!==false,quality:[.55,.65,.75,.85,.92,.96].includes(value.quality)?value.quality:.92};}catch{return{profile:'balanced',size:'a4',orientation:'portrait',searchable:true};}}
export function saveExportPreferences(value,storage=localStorage){const {profile,size,orientation,searchable,quality}=value;storage.setItem('waraqa-export-preferences',JSON.stringify({profile,size,orientation,searchable,quality}));}
